command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="e70d3ec5c91118acd113f2d90cb6a37f1c7c4ac8";$candidate="57556a17a199808ae0204b8d0528624aeb21b923";$branch="work/unc-network-shell-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network visual PrintWindow baseline fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network visual PrintWindow baseline"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network visual PrintWindow candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-visual-before2-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network visual PrintWindow worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network visual PrintWindow diff check failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "network visual PrintWindow Release build failed"}
 & python -u -X utf8 .\tests\winui\test_network_visual_gui.py --configuration Release --capture before
 if($LASTEXITCODE -ne 0){throw "network visual PrintWindow GUI failed"}
 Write-Host "NETWORK_VISUAL_BASELINE2_DIFF_CHECK=PASS"
 Write-Host "NETWORK_VISUAL_BASELINE2_RELEASE=PASS"
 Write-Host "NETWORK_VISUAL_BASELINE2_GUI=PASS"
 Write-Host "NETWORK_VISUAL_BASELINE_PRODUCT_MAIN=$main"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
